// Generates lib/src/bindings/onnxruntime_c_api.g.dart from the ONNX Runtime
// C header that `make ort-macos` fetches (tool/ort/include, release 1.31.0,
// sha256 pinned in the Makefile). Run via `make ffigen`, which also formats
// the output: the generated file is excluded from analysis but gate-format
// covers the whole tree.
//
// The ORT C API is one struct of function pointers (OrtApi) reached through
// OrtGetApiBase()->GetApi(version), so the bindings include exactly that
// function, the two structs and the enums and macros the wrapper reads; every
// other declaration arrives only as a transitive dependency of those.
import 'dart:io';

import 'package:ffigen/ffigen.dart';

const _enums = {
  'ONNXTensorElementDataType',
  'ONNXType',
  'OrtLoggingLevel',
  'OrtErrorCode',
  'GraphOptimizationLevel',
  'ExecutionMode',
  'OrtAllocatorType',
  'OrtMemType',
};

Future<void> main() async {
  final packageRoot = Platform.script.resolve('../');
  final include = packageRoot.resolve('tool/ort/include/');
  final header = include.resolve('onnxruntime_c_api.h');
  if (!File.fromUri(header).existsSync()) {
    stderr.writeln('${header.toFilePath()} missing: run `make ort-macos` first.');
    exitCode = 1;
    return;
  }
  final licence = File.fromUri(packageRoot.resolve('tool/ort/LICENSE'))
      .readAsStringSync()
      .trimRight()
      .split('\n')
      .map((l) => '// $l'.trimRight())
      .join('\n');

  final generator = FfiGenerator(
    input: Input(
      entryPoints: [header],
      include: (uri) => uri.toFilePath().startsWith(include.toFilePath()),
    ),
    output: Output(
      dart: DartOutput(
        path: packageRoot.resolve('lib/src/bindings/onnxruntime_c_api.g.dart'),
      ),
      style: const DynamicLibraryBindings(
        wrapperName: 'OnnxRuntimeBindings',
        wrapperDocComment:
            'ONNX Runtime C API 1.31.0: OrtGetApiBase and the OrtApi struct.',
      ),
      commentType: CommentType.none(),
      preamble:
          '''
// GENERATED by package:ffigen from onnxruntime_c_api.h (ONNX Runtime 1.31.0).
// Do not edit: run `make ffigen` (tool/ffigen.dart holds the filter).
//
// The header this was generated from is licensed as follows:
$licence

// ignore_for_file: type=lint, unused_import, unused_element, deprecated_member_use_from_same_package, experimental_member_use
''',
    ),
    visitors: [
      Visitor(
        func: (node) => node.isIncluded = node.name == 'OrtGetApiBase',
        struct: (node) =>
            node.isIncluded = node.name == 'OrtApiBase' || node.name == 'OrtApi',
        enumClass: (node) {
          node.isIncluded = _enums.contains(node.name);
          node.style = EnumStyle.intConstants;
          // C enums are `unsigned int` on arm64 Darwin, the only targets
          // (iOS device, macOS test host); ffigen's mimicking matches.
          node.silenceWarning = true;
        },
        macroConstant: (node) =>
            node.isIncluded = node.name == 'ORT_API_VERSION',
      ),
    ],
  );
  await generator.generate();
}
